const ANSI = /\x1b\[[0-9;?]*[A-Za-z]/g;
const NOTICE = /^(There (are|is) \d+ |You have \d+ |\d+ [\w ]+ notes? (have|has) been added)/;
const state = (globalThis.__saRoom ??= { lines: [], exitsAt: -1, last: null });

const payload = (event && event.payload) || {};
const chunk = String(payload.rawText ?? payload.text ?? '');
const lines = chunk.split('\n');
if (lines[lines.length - 1] === '') lines.pop();

for (const raw of lines) {
  const plain = raw.replace(ANSI, '').replace(/\r/g, '');

  const prompt = plain.match(/^<\d+\/\d+hp[^>]*> \[([^\]]+)\]/);
  if (prompt) {
    if (state.exitsAt >= 0) {
      const title = prompt[1].trim();
      const seg = state.lines;
      const titleAt = seg.findIndex((l) => l.trim() === title);
      if (titleAt >= 0 && titleAt < state.exitsAt) {
        const description = seg
          .slice(titleAt + 1, state.exitsAt)
          .map((l) => l.trim())
          .filter(Boolean)
          .join(' ');
        const exitsMatch = seg[state.exitsAt].match(/\[Exits:\s*([^\]]*)\]/);
        const exits = exitsMatch ? exitsMatch[1].split(/\s+/).filter((e) => /^[a-z]+$/i.test(e)) : [];

        // Everything between the exits line and the first empty line is the room's contents: indented lines are objects,
        // the rest are creatures. A line of exactly five spaces is an object with no description.
        const objects = [];
        const creatures = [];
        let unlisted = false;
        for (const l of seg.slice(state.exitsAt + 1)) {
          if (l === '') break;
          if (/^ {5}$/.test(l)) unlisted = true;
          else if (/^ {5}\S/.test(l)) objects.push(l.trim());
          else if (l.trim() && !NOTICE.test(l.trim())) creatures.push(l.trim());
        }
        state.last = { title, description, exits, objects, creatures, unlisted };
      }
    }
    state.lines = [];
    state.exitsAt = -1;
    continue;
  }

  state.lines.push(plain);
  if (state.lines.length > 80) {
    state.lines.shift();
    if (state.exitsAt >= 0) state.exitsAt--;
  }
  if (/^ ?\[Exits:/.test(plain)) state.exitsAt = state.lines.length - 1;
}

const BASE = 'http://localhost:5000';

// Copilot's hint tiers, when its local server is up: what you taught for this room first (instant), then the word list, the local model if it is allowed, and a
// ticket for Claude when nothing knows the room. Optional: with the server down this script is what it was, and the only thing added is a taught answer.
const COPILOT = (() => {
  try {
    return globalThis.localStorage?.getItem('copilot.api.base') || 'https://copilot.shatteredarchive.dev';
  } catch {
    return 'https://copilot.shatteredarchive.dev';
  }
})();

async function copilotHint(room) {
  const query = new URLSearchParams({ title: room.title, description: String(room.description || '').slice(0, 3900) });
  if ((room.exits || []).length) query.set('exits', room.exits.slice(0, 12).map((e) => String(e).slice(0, 9)).join(','));
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4000);
  try {
    const response = await fetch(`${COPILOT}/hints?${query}`, { signal: controller.signal });
    if (!response.ok) return null;
    const body = await response.json();
    return body && typeof body.tier === 'string' && Array.isArray(body.commands) ? body : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

const esc = (s) => String(s ?? '').replace(/\{/g, '{{');
const room = globalThis.__saRoom && globalThis.__saRoom.last;

if (!room) {
  writeTerminal('{Yhint: no room seen yet. Type look, then hint again.{x\n');
  return;
}

// 1. what you taught for this room answers at once
const smart = await copilotHint(room);
if (smart && smart.tier === 'learned' && smart.commands.length) {
  writeTerminal(`{C== Taught for {W${esc(room.title)}{C ==\n{x`);
  writeTerminal(`{G${esc(smart.commands.join('  |  '))}{x   {D(${esc((smart.notes || []).join('; ') || 'taught')}){x\n`);
  return;
}

// 2. the word list over the room text and what your logs say was tried here
const query = new URLSearchParams({ title: room.title, description: room.description, unlisted: String(room.unlisted) });
for (const o of room.objects || []) query.append('objects', o);
for (const e of room.exits || []) query.append('exits', e);

let res;
try {
  const response = await fetch(`${BASE}/api/agent/room-hints?${query}`);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  res = await response.json();
} catch (err) {
  writeTerminal(`{Rhint: the local service did not answer (${esc(err && err.message ? err.message : err)}).{x\n`);
  return;
}

const h = res && res.hints;
if (!h) {
  writeTerminal('{Rhint: unexpected reply from the service.{x\n');
  return;
}

writeTerminal(`{C== Hints for {W${esc(h.title)}{C ==\n{x`);
if (h.unlistedObjectSeen) writeTerminal('{Y!{x There is an unlisted object here (blank-indent line).\n');

for (const r of h.reactions || []) {
  writeTerminal(`{M* this room reacted to {W${esc(r.command)}{M{x   {D${esc(r.reply)}${r.count > 1 ? ' x' + r.count : ''}{x\n`);
}
if ((h.roomSocials || []).length) writeTerminal(`{CRoom-level (no target):{x ${esc(h.roomSocials.join('  |  '))}\n`);
for (const f of h.findings || []) {
  const label =
    f.status === 'object' ? '{GOBJECT here{x' : f.status === 'extra-description' ? '{Dextra description only, not an object{x' : '{Ytext only: object or extra description?{x';
  writeTerminal(`{W${esc(f.keyword)}{x  ${label}   {D${esc(f.evidence.join('; '))}{x\n`);
  if (f.next.length) writeTerminal(`   {Cnext:{x ${esc(f.next.join('  |  '))}\n`);
  if ((f.socials || []).length) writeTerminal(`   {Csocials:{x ${esc(f.socials.join('  |  '))}\n`);
}
for (const c of h.candidates) {
  const src = c.from === 'objects' ? ' [object list]' : '';
  writeTerminal(`{G${esc(c.commands.join('  |  '))}{x   {D(${esc(c.phrase)}: ${esc(c.kind)}${src}){x\n`);
}
for (const w of (h.findings && h.findings.length ? [] : h.worked)) {
  const what = w.outcome === 'blank' ? 'answers with nothing' : w.outcome === 'notContainer' ? 'not a container' : w.sample ? w.sample : 'works';
  writeTerminal(`{g+ ${esc(w.command)}{x   {D${esc(what)}${w.count > 1 ? ' x' + w.count : ''}{x\n`);
}
for (const s of h.struckOff) {
  writeTerminal(`{D- ${esc(s.command)}   rejected${s.count > 1 ? ' x' + s.count : ''} in your logs{x\n`);
}
if (!h.candidates.length && !h.worked.length) writeTerminal('{DNothing in this room matches the hint list. Try hint:ai.{x\n');

// 3. the slower tiers, only if Copilot has them
if (smart && smart.tier === 'local' && smart.commands.length) {
  writeTerminal(`{CLocal model:{x {G${esc(smart.commands.join('  |  '))}{x   {D(check each one, it can be wrong){x\n`);
}
if (smart && smart.tier === 'escalated') {
  writeTerminal('{DNo tier knows this room yet: a ticket was filed for Claude. When you find what works here, type hint:teach <command> | <command> and the next hint here answers at once.{x\n');
}

const BASE = 'http://localhost:5000';

const esc = (s) => String(s ?? '').replace(/\{/g, '{{');
const room = globalThis.__saRoom && globalThis.__saRoom.last;

if (!room) {
  writeTerminal('{Yhint:ai: no room seen yet. Type look, then hint:ai again.{x\n');
  return;
}
if (globalThis.__saHintAiBusy) {
  writeTerminal('{Yhint:ai: still waiting for the last question; one at a time.{x\n');
  return;
}

globalThis.__saHintAiBusy = true;
try {
  let status;
  try {
    const r = await fetch(`${BASE}/api/agent/room-hints/ai/status`);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    status = (await r.json()).status;
  } catch (err) {
    writeTerminal(`{Rhint:ai: the local service did not answer (${esc(err && err.message ? err.message : err)}).{x\n`);
    return;
  }
  if (!status.configured) {
    writeTerminal('{Rhint:ai: this server has no local AI configured (ROOM_HINTS_OLLAMA_URL is unset).{x\n');
    return;
  }
  if (!status.reachable || !status.modelInstalled) {
    const why = !status.reachable ? `Ollama is not reachable${status.error ? ' (' + status.error + ')' : ''}` : `model ${status.model} is not installed`;
    writeTerminal(`{Rhint:ai: ${esc(why)}.{x\n`);
    return;
  }

  const warm = status.modelLoaded ? 'already loaded' : 'NOT loaded yet: the first answer can take about two minutes';
  writeTerminal(`{Chint:ai: asking {W${esc(status.model)}{C about {W${esc(room.title)}{C (${warm}). Nothing is sent to the game.{x\n`);
  const started = Date.now();

  let body;
  try {
    const response = await fetch(`${BASE}/api/agent/room-hints/ai`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: room.title,
        description: room.description,
        exits: room.exits || [],
        objects: room.objects || [],
        creatures: room.creatures || [],
        unlisted: !!room.unlisted,
      }),
    });
    body = await response.json();
  } catch (err) {
    writeTerminal(`{Rhint:ai: the request failed (${esc(err && err.message ? err.message : err)}).{x\n`);
    return;
  }

  const result = body && body.result;
  const secs = ((Date.now() - started) / 1000).toFixed(1);
  if (!result || !result.ok) {
    writeTerminal(`{Rhint:ai: ${esc((result && result.error) || (body && body.error) || 'no answer')}{x\n`);
    return;
  }

  writeTerminal(`{C== AI hint for {W${esc(room.title)}{C (${esc(result.model)}, ${secs}s) ==\n{x`);
  for (const line of String(result.answer).split(/\r?\n/)) {
    if (line.trim()) writeTerminal(`{G${esc(line.trim())}{x\n`);
  }
  writeTerminal('{DA local model wrote this from the room text; check each command, it can be wrong.{x\n');
} finally {
  globalThis.__saHintAiBusy = false;
}

// hint:teach <command> | <command> ... : tells Copilot what works in the room you stand in, so the next `hint` here is answered at once from what you taught
// (the learned tier). Several commands are separated by | (a ; would be split by the client before this script runs). Nothing is sent to the game.
const COPILOT = (() => {
  try {
    return globalThis.localStorage?.getItem('copilot.api.base') || 'https://copilot.shatteredarchive.dev';
  } catch {
    return 'https://copilot.shatteredarchive.dev';
  }
})();

const esc = (s) => String(s ?? '').replace(/\{/g, '{{');
const room = globalThis.__saRoom && globalThis.__saRoom.last;
const typed = String((event && event.payload && event.payload.vars && event.payload.vars.RULE) || '').trim();
const commands = typed
  .split('|')
  .map((c) => c.trim())
  .filter(Boolean);

if (!room) {
  writeTerminal('{Yhint:teach: no room seen yet. Type look, then hint:teach again.{x\n');
  return;
}
if (commands.length === 0) {
  writeTerminal('{Yhint:teach: say what works here, for example: hint:teach enter orb | look in gate{x\n');
  return;
}

try {
  const response = await fetch(`${COPILOT}/hints/rules`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: room.title, commands, source: 'owner', note: 'taught in the game with hint:teach' }),
  });
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    const why = [body && body.error, ...((body && body.details) || [])].filter(Boolean).join(': ') || `HTTP ${response.status}`;
    writeTerminal(`{Rhint:teach: not taken (${esc(why)}).{x\n`);
    return;
  }
  writeTerminal(`{Ghint:teach: remembered for {W${esc(room.title)}{G: ${esc(commands.join('  |  '))}{x\n`);
} catch (err) {
  writeTerminal(`{Rhint:teach: Copilot's server did not answer (${esc(err && err.message ? err.message : err)}). It must be running for a hint to be taught.{x\n`);
}
